OLD = "d" + "ev"  # built from parts: this file is scanned by the class test it helps to check
RAISE = (
    "            raise _RenamedStage(\n"
    '                f"environment: {_OLD_STAGE} was renamed to {STAGES[0]}; write environment: {STAGES[0]} "\n'
    "                f\"(allowed values: {', '.join(STAGES)})\"\n"
    "            )"
)


def mutant(name, file, old, new, killer, expect, param=""):
    return Mutant(
        name, file, old, new, expect, test_file=TEST, only_test=killer, pinned=PIN + killer + param
    )


def crash_mutant(name, file, old, new, killer, crash_type, param=""):
    """A mutant that lets a library error through: the killer test dies with that exception class."""
    return Mutant(
        name,
        file,
        old,
        new,
        crash_type,
        allow_crash=True,
        crash_type=crash_type,
        test_file=TEST,
        only_test=killer,
        pinned=PIN + killer + param,
    )


TRACE = "tests/test_q8a1_f_string_trace.py"


def trace_mutant(name, file, old, new, killer, expect):
    """A mutant killed by a test of the round-10 trace file (tests/test_q8a1_f_string_trace.py)."""
    return Mutant(
        name,
        file,
        old,
        new,
        expect,
        test_file=TRACE,
        only_test=killer,
        pinned="tests/test_q8a1_f_string_trace::" + killer,
    )


def other_crash_mutant(name, file, old, new, test_file, killer, crash_type, param=""):
    """A mutant that lets a library error through, killed by a test in another file (the test dies with that class)."""
    return Mutant(
        name,
        file,
        old,
        new,
        crash_type,
        allow_crash=True,
        crash_type=crash_type,
        test_file=test_file,
        only_test=killer,
        pinned=test_file[:-3] + "::" + killer + param,
    )


def other_mutant(name, file, old, new, test_file, killer, expect, param=""):
    """A mutant killed by a test in another file of `tests` (it must be listed in the copied tests below)."""
    return Mutant(
        name,
        file,
        old,
        new,
        expect,
        test_file=test_file,
        only_test=killer,
        pinned=test_file[:-3] + "::" + killer + param,
    )


